userDefinedLinkHintCss:
/* Charcoal + cyan + Monocraft. No remote fonts or external stylesheets. */
div > .vimiumHintMarker {
  padding: 2px 5px;
  border: 1px solid #191919;
  border-radius: 4px;
  background: #67ffeb;
  box-shadow: 0 2px 6px #0008, 0 0 0 1px #67ffeb99;
}
div > .vimiumHintMarker span {
  color: #191919;
  font-family: "Monocraft Nerd Font", "Monocraft", monospace;
  font-size: 12px;
  font-weight: normal;
  line-height: 1.2;
  text-shadow: none;
}
div > .vimiumHintMarker > .matchingCharacter {
  color: #456c64;
  text-decoration: line-through;
}
div > .vimiumActiveHintMarker {
  background: #f8f8f2;
  outline: 2px solid #67ffeb;
}
div > .vimiumActiveHintMarker span { color: #191919 !important; }

/* Vimium 2.2.1's search, bookmark and tab picker share this component. */
#vomnibar {
  font-family: "Monocraft Nerd Font", "Monocraft", monospace;
  background: #191919;
  color: #f8f8f2;
  border: 2px solid #67ffeb;
  border-radius: 6px;
  box-shadow: 0 8px 24px #0009;
  overflow: hidden;
}
#vomnibar .vomnibarSearchArea {
  padding: 12px;
  background: #191919;
  border-bottom: 1px solid #404040;
  border-radius: 0;
}
#vomnibar input {
  height: 42px;
  padding: 8px 10px;
  font-family: inherit;
  font-size: 16px;
  line-height: 24px;
  color: #f8f8f2;
  caret-color: #67ffeb;
  background: #242424;
  border: 1px solid #404040;
  border-radius: 4px;
  box-shadow: none;
}
#vomnibar input:focus { border-color: #67ffeb; }
#vomnibar input::selection { background: #67ffeb; color: #191919; }
#vomnibar ul { background: #191919; padding: 6px; }
#vomnibar li {
  padding: 9px 10px;
  margin: 2px 0;
  border: 1px solid transparent;
  border-radius: 4px;
  font-size: 13px;
  line-height: 1.45;
  color: #f8f8f2;
}
#vomnibar li:last-of-type { border-bottom: 1px solid transparent; }
#vomnibar li .vomnibarBottomHalf { font-size: 11px; margin-top: 3px; }
#vomnibar li .vomnibarTitle, #vomnibar li em { color: #f8f8f2; }
#vomnibar li .vomnibarSource { color: #aaaaaa; }
#vomnibar li .vomnibarUrl { color: #a3c5be; }
#vomnibar li .vomnibarMatch,
#vomnibar li .vomnibarTitle .vomnibarMatch,
#vomnibar li em .vomnibarMatch {
  color: #67ffeb;
  font-weight: normal;
  text-decoration: underline;
  text-underline-offset: 3px;
}
#vomnibar li.vomnibarSelected {
  background: #223b37;
  border: 1px solid #67ffeb;
}
